from pybricks.hubs import PrimeHub
from pybricks.parameters import Color, Direction, Port, Stop
from pybricks.pupdevices import ColorSensor, Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

from colores import detectar_color

# Set up.
coloractual = 0
prime_hub = PrimeHub()
motorizq = Motor(Port.B, Direction.COUNTERCLOCKWISE)
motorder = Motor(Port.E, Direction.CLOCKWISE)
motoratras = Motor(Port.C, Direction.CLOCKWISE)
motoradelante = Motor(Port.D, Direction.CLOCKWISE)
drive_base = DriveBase(motorizq, motorder, 55, 176)
SENSORFRENTE = ColorSensor(Port.F)
SENSORPISO = ColorSensor(Port.A)

def primera_parte():
    drive_base.straight(260)
    drive_base.turn(90)
    drive_base.straight(1540)
    drive_base.turn(90)
    motor_trasero_abrir()
    drive_base.straight(-145)
    motor_trasero_cerrarar()
    # YA TIENE EL PRIMER CABLE
    drive_base.straight(550)
    drive_base.turn(75)
    drive_base.straight(-470)
    motor_trasero_abrir()
    # DEJA EL PRIMER CABLE
    drive_base.straight(490)
    drive_base.turn(105)
    drive_base.straight(-250)
    motor_trasero_cerrarar()
    # YA TIENE EL SEGUNDO CABLE
    drive_base.straight(-80)
    # SE ACOMODA CON LA PARED
    drive_base.straight(165)
    drive_base.turn(-85)
    drive_base.straight(-460)
    motor_trasero_abrir()
    motoratras.run_angle(500, 40)
    # DEJA EL SEGUNDO CABLE
    drive_base.straight(50)
    drive_base.turn(36)
    drive_base.straight(900)
    drive_base.turn(-40)
    drive_base.straight(225)
    drive_base.turn(90)
    drive_base.straight(161)
    motor_adelante_cerrar_()
    # AGARRA EL MICROFONO
    drive_base.straight(-170)
    drive_base.turn(-89)
    drive_base.straight(690)
    drive_base.arc(88, angle=181)
    drive_base.turn(-183)
    motoratras.run_angle(500, 20)
    drive_base.straight(-1430)
    drive_base.settings(straight_speed=430)
    # EMPUJA LOS INSTRUMENTOS
    drive_base.straight(290)
    motor_trasero_cerrarar()
    drive_base.turn(-90)
    drive_base.straight(-100)
    # SE ACOMODA CON LA PARED
    drive_base.straight(645)
    drive_base.turn(-90)
    drive_base.straight(395)
    motor_adelente_abrir()
    # DEJO EL MICROFONO
    drive_base.straight(-500)
    drive_base.arc(88, angle=-66)
    drive_base.arc(-88, angle=-66)
    drive_base.straight(-1370, then=Stop.COAST)
    # choca con la pared y espera
    wait(200)

def primera_parte_pruebas():
    drive_base.straight(260)
    drive_base.turn(90)
    drive_base.straight(1540)
    drive_base.turn(90)
    motor_trasero_abrir()
    drive_base.straight(-145)
    motor_trasero_cerrarar()
    # YA TIENE EL PRIMER CABLE
    drive_base.straight(550)
    drive_base.turn(75)
    drive_base.straight(-470)
    motor_trasero_abrir()
    # DEJA EL PRIMER CABLE
    drive_base.straight(490)
    drive_base.turn(105)
    drive_base.straight(-250)
    motor_trasero_cerrarar()
    # YA TIENE EL SEGUNDO CABLE
    drive_base.straight(-80)
    # SE ACOMODA CON LA PARED
    drive_base.straight(165)
    drive_base.turn(-85)
    drive_base.straight(-460)
    motor_trasero_abrir()
    motoratras.run_angle(500, 40)
    # DEJA EL SEGUNDO CABLE
    drive_base.straight(50)
    drive_base.turn(36)
    drive_base.straight(900)
    drive_base.turn(-40)
    drive_base.straight(225)
    drive_base.turn(90)
    drive_base.straight(161)
    motor_adelante_cerrar_()
    # AGARRA EL MICROFONO
    drive_base.straight(-170)
    drive_base.turn(-89)
    drive_base.straight(690)
    drive_base.arc(88, angle=181)
    drive_base.turn(-183)
    drive_base.straight(-1430)
    drive_base.settings(straight_speed=430)
    # EMPUJA LOS INSTRUMENTOS
    drive_base.turn(-15)
    drive_base.straight(290)
    motor_trasero_cerrarar()
    drive_base.turn(-75)
    drive_base.straight(-100)
    # SE ACOMODA CON LA PARED
    drive_base.straight(645)
    drive_base.turn(-90)
    drive_base.straight(345)
    motor_adelente_abrir()
    # DEJO EL MICROFONO
    drive_base.straight(-500)
    drive_base.arc(88, angle=-66)
    drive_base.arc(-88, angle=-66)
    drive_base.straight(-1370, then=Stop.COAST)
    # choca con la pared y espera
    wait(200)

def motor_adelente_abrir():
    motoradelante.run_until_stalled(-200, Stop.COAST, 50)
    motoradelante.run_angle(-500, 1)

def choca_pared():
    drive_base.settings(straight_speed=150)
    drive_base.straight(250)
    drive_base.straight(-20)
    drive_base.settings(straight_speed=430)

def motor_adelante_cerrar_():
    motoradelante.run_until_stalled(800, Stop.COAST, 50)
    motoradelante.run_angle(500, 1)

def motor_trasero_abrir():
    motoratras.run_until_stalled(-300, Stop.BRAKE, 30)
    motoratras.run_angle(-300, 3)

def detectar_y_guardar_color():
    global coloractual
    wait(200)
    coloractual = detectar_color()
    print('El robot detectò: →', coloractual)

def motor_trasero_cerrarar():
    motoratras.run_angle(300, 3)
    motoratras.run_until_stalled(300, Stop.BRAKE, 30)

def MICROFONO_Y_CABLE():
    drive_base.straight(-80, then=Stop.COAST)
    drive_base.arc(-88, angle=17)
    drive_base.straight(1080)
    my_1_AVANZAR_HASTA_DETECTAR(200, Color.NONE)
    drive_base.turn(-73)
    my_1_AVANZAR_HASTA_DETECTAR(200, Color.NONE)
    drive_base.straight(30)
    motor_adelante_cerrar_()
    drive_base.straight(-60)
    my_1_RETROCEDER_HASTA_DETECTAR(-200, Color.NONE)
    drive_base.turn(-90)
    drive_base.straight(-460)
    my_1_RETROCEDER_HASTA_DETECTAR(-200, Color.NONE)
    drive_base.straight(20)
    drive_base.turn(-90)
    motor_trasero_abrir()
    drive_base.straight(-150)
    motor_trasero_cerrarar()
    drive_base.straight(510)
    drive_base.turn(75)
    drive_base.straight(-480)
    motor_trasero_abrir()
    drive_base.straight(25)
    drive_base.arc(-88, angle=75)
    motor_adelente_abrir()

def my_1_AVANZAR_HASTA_DETECTAR(VELOCIDAD, COLOR):
    drive_base.drive(VELOCIDAD, 0)
    while not SENSORPISO.color() == COLOR:
        wait(0)
    drive_base.brake()
    prime_hub.speaker.beep(1000, 100)

def deteccion_de_colores():
    drive_base.reset(0, 0)
    drive_base.straight(1020)
    drive_base.turn(90)
    choca_pared()
    motor_adelante_cerrar_()
    detectar_y_guardar_color()
    if coloractual == 1:
        BLOQUE_UNICO_PARA_VAGOS()
        drive_base.straight(480)
        drive_base.turn(90)
        drive_base.straight(95)
        motor_adelente_abrir()
        drive_base.straight(-235)
        drive_base.turn(90)
        drive_base.straight(350)
    elif coloractual == 2:
        BLOQUE_UNICO_PARA_VAGOS()
        drive_base.straight(274)
        drive_base.turn(-90)
        drive_base.straight(575)
        motor_adelente_abrir()
        drive_base.straight(-425)
        drive_base.turn(-90)
        drive_base.straight(150)
    elif coloractual == 3:
        BLOQUE_UNICO_PARA_VAGOS()
        drive_base.straight(370)
        drive_base.turn(-90)
        drive_base.straight(410)
        motor_adelente_abrir()
        drive_base.straight(-260)
        drive_base.turn(-90)
        drive_base.straight(300)
    elif coloractual == 0 or coloractual == 4:
        BLOQUE_UNICO_PARA_VAGOS()
        drive_base.straight(490)
        motor_adelente_abrir()
        drive_base.straight(-70)
        drive_base.arc(-88, angle=-140)
        drive_base.arc(88, angle=40)
        drive_base.straight(250)
    elif coloractual == -1:
        motor_adelente_abrir()
        drive_base.straight(-250)
        drive_base.turn(90)
        drive_base.straight(130)
        drive_base.turn(-90)
        drive_base.straight(150)
    else:
        pass
    choca_pared()
    motor_adelante_cerrar_()
    detectar_y_guardar_color()
    if coloractual == 1:
        BLOQUE_UNICO_PARA_VAGOS()
        drive_base.straight(250)
        drive_base.turn(90)
        drive_base.straight(305)
        drive_base.turn(-90)
        drive_base.straight(180)
        motor_adelente_abrir()
        prime_hub.speaker.beep(500, 100)
        drive_base.straight(-180)
        drive_base.turn(90)
        drive_base.straight(-435)
        drive_base.turn(90)
    elif coloractual == 2:
        BLOQUE_UNICO_PARA_VAGOS()
        drive_base.straight(200)
        drive_base.turn(-90)
        drive_base.straight(345)
        drive_base.turn(28)
        drive_base.straight(130)
        motor_adelente_abrir()
        drive_base.straight(-130)
        drive_base.turn(-28)
        drive_base.straight(-200)
        drive_base.turn(-90)
    elif coloractual == 3:
        BLOQUE_UNICO_PARA_VAGOS()
        drive_base.straight(280)
        drive_base.turn(-90)
        drive_base.straight(333)
        drive_base.turn(90)
        drive_base.straight(35)
        motor_adelente_abrir()
        drive_base.straight(-150)
        drive_base.turn(90)
        drive_base.straight(193)
        drive_base.turn(90)
    elif coloractual == 4 or coloractual == 0:
        BLOQUE_UNICO_PARA_VAGOS()
        prime_hub.speaker.beep(500, 100)
        drive_base.straight(230)
        drive_base.turn(90)
        drive_base.straight(145)
        drive_base.turn(-90)
        drive_base.straight(250)
        motor_adelente_abrir()
        prime_hub.speaker.beep(500, 100)
        drive_base.straight(-180)
        drive_base.turn(90)
        drive_base.straight(-275)
        drive_base.turn(90)
        drive_base.straight(200)
    else:
        pass
    RAPIDAMENTE_EL_ROJO()
    RAPIDO_Y_FURIOSO_VERDE()

def my_1_RETROCEDER_HASTA_DETECTAR(VELOCIDAD, COLOR):
    drive_base.drive(VELOCIDAD, 0)
    while not SENSORPISO.color() == COLOR:
        wait(0)
    drive_base.brake()
    prime_hub.speaker.beep(1000, 100)

def BLOQUE_UNICO_PARA_VAGOS():
    drive_base.settings(straight_speed=500)
    drive_base.settings(turn_rate=250)
    drive_base.straight(-135)
    drive_base.turn(-180)
    drive_base.straight(-180)
    drive_base.reset(0, 0)
    drive_base.settings(straight_speed=420)
    drive_base.settings(turn_rate=150)

def RAPIDAMENTE_EL_ROJO():
    # Notas interesantes
    # Rueda derecha adelante → Radio - | Ángulo +
    # Ruerda izquierda adelante → | Radio + | Ángulo +
    # Rueda derecha atras → | Radio - | Ángulo -
    # Rueda izquierda atras → | Radio + | Ángulo -

    choca_pared()
    motor_adelante_cerrar_()
    drive_base.arc(-88, angle=-128)
    drive_base.arc(88, angle=52)
    drive_base.straight(300)
    motor_adelente_abrir()
    drive_base.straight(-280)
    drive_base.turn(90)
    drive_base.straight(-245)
    drive_base.turn(90)
    drive_base.straight(70)

def SIMPLEMENTE_el_rojo_():
    choca_pared()
    motor_adelante_cerrar_()
    BLOQUE_UNICO_PARA_VAGOS()
    drive_base.straight(200)
    drive_base.turn(90)
    drive_base.straight(120)
    drive_base.turn(-90)
    drive_base.straight(250)
    motor_adelente_abrir()
    drive_base.straight(-280)
    drive_base.turn(90)
    drive_base.straight(-245)
    drive_base.turn(90)
    drive_base.straight(70)

def SIMPLEMENTE_el_verde():
    choca_pared()
    motor_adelante_cerrar_()
    BLOQUE_UNICO_PARA_VAGOS()
    drive_base.straight(200)
    drive_base.turn(90)
    drive_base.straight(80)
    drive_base.turn(-90)
    drive_base.straight(180)
    motor_adelente_abrir()
    drive_base.straight(-50)

def RAPIDO_Y_FURIOSO_VERDE():
    choca_pared()
    motor_adelante_cerrar_()
    drive_base.arc(-88, angle=-115)
    drive_base.arc(88, angle=65)
    drive_base.straight(210)
    motor_adelente_abrir()


# The main program starts here.
drive_base.use_gyro(True)
drive_base.reset(0, 0)
drive_base.settings(straight_speed=420)
drive_base.settings(straight_acceleration=800)
drive_base.settings(turn_acceleration=775)
motor_adelente_abrir()
MICROFONO_Y_CABLE()
